with with_dims as (select a.*, p.status as order_status, p.order_date from payments a inner join orders p on a.order_id = p.id) select case when amount >= 1410 then 'LARGE' else 'SMALL' end as amount_tier, min(amount) as min_amount, count(*) filter (where status = 'SUCCESS') as success_rows, count(case when method = 'cash' then 1 end) as cash_count from with_dims group by case when amount >= 1410 then 'LARGE' else 'SMALL' end having min_amount > 0 order by success_rows desc nulls last
